cd /tank/nxeon-wt-invlogo; cat > test/invoice-logo.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import {
  renderInvoiceHTML,
  invoiceDescriptionLines,
  MAX_DESC_LINES,
  MAX_DESC_CHARS,
  type InvoiceBranding,
} from "../lib/invoices";
import { renderInvoicePDF, loadInvoiceLogo, _resetInvoiceLogoCache } from "../lib/invoice-pdf";

const branding: InvoiceBranding = { numberPrefix: "INV-", brandName: "Nxeon", legalName: "", address: "" };

function inv(items: { description: string; qty: number; unitCents: number; amountCents: number }[], status = "PAID") {
  const sub = items.reduce((n, i) => n + i.amountCents, 0);
  return {
    id: "i1", number: 12, userId: "u1", status, amountCents: sub, taxCents: 0, refundedCents: 0,
    description: "Sample invoice", lineItems: items, createdAt: new Date("2026-10-01"), paidAt: new Date("2026-10-01"),
    paidBrand: "visa", paidLast4: "4242", periodStart: null, periodEnd: null, taxRatePercent: null, taxCountry: null,
  } as never;
}
const user = { name: "Ada <b>Lovelace</b>", email: "ada@example.com" };
const one = [{ description: "VPS plan", qty: 1, unitCents: 1000, amountCents: 1000 }];
const multi = [{ description: "Custom VPS\n6 vCPU <script>alert(1)</script>\r\n\n32 GB RAM", qty: 1, unitCents: 5000, amountCents: 5000 }];

test("HTML: real logo on dark header band, absolute URL, no fake svg", () => {
  process.env.APP_URL = "https://nxeon.cloud/";
  const html = renderInvoiceHTML(inv(one), user, branding);
  assert.match(html, /<img class="logo" src="https:\/\/nxeon\.cloud\/logo\.png" alt="Nxeon"/);
  assert.match(html, /class="hdr"/);
  assert.ok(!html.includes("nxg"));
  assert.ok(!html.includes("<svg"));
  assert.match(html, /print-color-adjust: exact/);
});

test("HTML: white-label brand shows name text, not the Nxeon logo", () => {
  const html = renderInvoiceHTML(inv(one), user, { ...branding, brandName: "Acme <Host>" });
  assert.ok(!html.includes("/logo.png"));
  assert.ok(html.includes("Acme &lt;Host&gt;"));
});

test("HTML: multi-line description splits into escaped sub-lines; single line unchanged", () => {
  const html = renderInvoiceHTML(inv(multi), user, branding);
  assert.match(html, /<td class="desc">Custom VPS<div class="dsub">6 vCPU &lt;script&gt;/);
  assert.equal((html.match(/class="dsub"/g) ?? []).length, 2);
  assert.ok(!html.includes("<script>alert"));
  assert.match(renderInvoiceHTML(inv(one), user, branding), /<td class="desc">VPS plan<\/td>/);
});

test("description lines: caps and never throws", () => {
  assert.deepEqual(invoiceDescriptionLines("a"), ["a"]);
  assert.deepEqual(invoiceDescriptionLines(""), [""]);
  assert.deepEqual(invoiceDescriptionLines(undefined), [""]);
  const many = invoiceDescriptionLines(Array.from({ length: 40 }, (_, i) => `l${i}`).join("\n"));
  assert.equal(many.length, MAX_DESC_LINES);
  const long = invoiceDescriptionLines("x".repeat(5000));
  assert.ok(long.join("").length <= MAX_DESC_CHARS);
});

test("PDF: valid for 1-line, multi-line, many-rows and logo-missing", async () => {
  const b1 = await renderInvoicePDF(inv(one), user, branding);
  assert.equal(b1.subarray(0, 4).toString(), "%PDF");
  const b2 = await renderInvoicePDF(inv(multi), user, branding);
  assert.equal(b2.subarray(0, 4).toString(), "%PDF");
  const rows = Array.from({ length: 30 }, (_, i) => ({ description: `Item ${i}\nspec a\nspec b`, qty: 1, unitCents: 100, amountCents: 100 }));
  const b3 = await renderInvoicePDF(inv(rows), user, branding);
  assert.equal(b3.subarray(0, 4).toString(), "%PDF");
  assert.ok((b3.toString("latin1").match(/\/Type \/Page\b/g) ?? []).length >= 2);
  // logo present -> bigger than the logo-less fallback
  assert.ok(loadInvoiceLogo());
  const cwd = process.cwd();
  try {
    process.chdir("/");
    _resetInvoiceLogoCache();
    const orig = process.env.NODE_ENV;
    const b4 = await renderInvoicePDF(inv(one), user, branding);
    assert.equal(b4.subarray(0, 4).toString(), "%PDF");
    process.env.NODE_ENV = orig;
  } finally {
    process.chdir(cwd);
    _resetInvoiceLogoCache();
  }
});
EOF
